function UICultivateEquipSuitTitleNodeMB:RefreshUI(suitName, icon)
    self.SuitNameText.text = localize("【_name_套装】", {_name_ = suitName})

    local isShow = not string.isEmpty(icon)
    KTool.SetActive(self.Professional.gameObject, isShow)
    if isShow then
        self.ImgIcon:LoadSprite(icon)
    end

    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.SuitTitleNode)
end
